BEGIN;
-- Chad is a Complete-only, content-only CRM proposal boundary. It has no
-- message queue, recipient contact, consent, calendar, lead/follow-up mutation,
-- payment, membership, tool, SQL, or outbound adapter.
INSERT INTO hon.permissions(code,description,is_sensitive,is_staff_assignable) VALUES
 ('crm.assistant.follow_up_draft','Complete direct staff may request a bounded Chad follow-up content proposal for a permitted current lead',true,true)
ON CONFLICT(code) DO NOTHING;
INSERT INTO hon.role_permissions(role_id,organization_id,permission_code)
 SELECT id,organization_id,'crm.assistant.follow_up_draft' FROM hon.roles WHERE is_system_role AND code='OWNER' ON CONFLICT DO NOTHING;

ALTER TABLE hon.ai_invocation_plans DROP CONSTRAINT ai_invocation_plans_task_class_check, DROP CONSTRAINT ai_invocation_plans_check;
ALTER TABLE hon.ai_invocation_plans ADD CHECK(task_class IN('SUMMARIZE','ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING','DRAFT_FOLLOW_UP')),
 ADD CHECK((task_class='SUMMARIZE' AND risk_class='LOW') OR (task_class IN('ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING','DRAFT_FOLLOW_UP') AND risk_class='MODERATE'));
CREATE OR REPLACE FUNCTION hon.validate_ai_invocation_plan_input(p_data jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE keys text[]:=ARRAY['expectedVersion','expectedState','agentKey','modality','taskClass','inputBudget','outputBudget','maxProviderCostMicrounits']; f text;
BEGIN
 IF p_data IS NULL OR jsonb_typeof(p_data)<>'object' OR NOT p_data ?& keys OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>ALL(keys)) THEN RAISE EXCEPTION 'Invalid AI planning metadata shape' USING ERRCODE='22023'; END IF;
 FOREACH f IN ARRAY ARRAY['expectedVersion','inputBudget','outputBudget','maxProviderCostMicrounits'] LOOP IF jsonb_typeof(p_data->f)<>'number' OR p_data->>f !~ '^[0-9]+$' OR (p_data->>f)::numeric>2147483646 THEN RAISE EXCEPTION 'Invalid AI planning integer' USING ERRCODE='22023'; END IF; END LOOP;
 IF (p_data->>'expectedVersion')::integer<1 OR (p_data->>'inputBudget')::integer NOT BETWEEN 1 AND 128000 OR (p_data->>'outputBudget')::integer NOT BETWEEN 1 AND 16000 OR (p_data->>'maxProviderCostMicrounits')::integer NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'AI planning budget or version out of range' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_data->'expectedState')<>'string' OR jsonb_typeof(p_data->'agentKey')<>'string' OR jsonb_typeof(p_data->'modality')<>'string' OR jsonb_typeof(p_data->'taskClass')<>'string' OR p_data->>'expectedState' NOT IN('READY','THINKING') OR p_data->>'agentKey' NOT IN('alex','chad','maya','marcus','jordan','claire','lena','eian') OR p_data->>'modality'<>'TEXT' OR p_data->>'taskClass' NOT IN('SUMMARIZE','ANALYZE','DRAFT_MARKETING','DRAFT_TEACHING','DRAFT_FOLLOW_UP') THEN RAISE EXCEPTION 'Unregistered AI planning metadata' USING ERRCODE='22023'; END IF;
END $$;

CREATE TABLE hon.chad_follow_up_invocations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, school_id uuid NOT NULL, requested_by uuid NOT NULL REFERENCES hon.principals(id),
 lead_id uuid NOT NULL, lead_version integer NOT NULL CHECK(lead_version BETWEEN 1 AND 999999999), purpose text NOT NULL CHECK(purpose IN('INTRODUCTION','CHECK_IN','TRIAL_REMINDER','REENGAGEMENT')),
 work_item_id uuid NOT NULL, plan_id uuid, provider_request_id uuid NOT NULL DEFAULT gen_random_uuid(), request_hash text NOT NULL, idempotency_key uuid NOT NULL,
 status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED','SENDING','UNKNOWN','FAILED','AWAITING_APPROVAL','APPROVED','REJECTED')),
 reason text CHECK(reason IN('CONFIGURATION_REQUIRED','NO_ELIGIBLE_ROUTE','CUSTOMER_BUDGET_EXCEEDED','UNSUPPORTED_PROVIDER','INVALID_REQUEST','PROVIDER_REJECTED','PROVIDER_UNKNOWN','ROUTE_STALE','RESULT_BUDGET_EXCEEDED','LEAD_STALE')),
 reserved_credits integer NOT NULL DEFAULT 0 CHECK(reserved_credits BETWEEN 0 AND 3), action_request_id uuid, usage_id uuid REFERENCES hon.ai_usage_ledger(id), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(lead_id,organization_id,school_id) REFERENCES hon.crm_leads(id,organization_id,school_id), FOREIGN KEY(work_item_id,organization_id,school_id) REFERENCES hon.work_items(id,organization_id,school_id), FOREIGN KEY(plan_id) REFERENCES hon.ai_invocation_plans(id), FOREIGN KEY(action_request_id,organization_id,school_id) REFERENCES hon.action_requests(id,organization_id,school_id),
 UNIQUE(id,organization_id,school_id), UNIQUE(organization_id,school_id,requested_by,idempotency_key), UNIQUE(provider_request_id), UNIQUE(work_item_id), UNIQUE(plan_id), UNIQUE(action_request_id), UNIQUE(usage_id), CHECK(request_hash~'^[a-f0-9]{64}$')
);
CREATE TABLE hon.chad_follow_up_drafts (
 invocation_id uuid PRIMARY KEY, organization_id uuid NOT NULL, school_id uuid NOT NULL, lead_id uuid NOT NULL, subject text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(invocation_id,organization_id,school_id) REFERENCES hon.chad_follow_up_invocations(id,organization_id,school_id), FOREIGN KEY(lead_id,organization_id,school_id) REFERENCES hon.crm_leads(id,organization_id,school_id),
 CHECK(length(btrim(subject)) BETWEEN 1 AND 120), CHECK(length(btrim(content)) BETWEEN 1 AND 3000), CHECK(subject !~* '(-----BEGIN|Bearer[[:space:]]+|\msk[-_][A-Za-z0-9_-]+|\meyJ[A-Za-z0-9_-]+\.eyJ|(?:api[ _-]?key|password|secret|authorization)[[:space:]]*[:=]|https?://|\mwww\.|[\x01-\x08\x0b\x0c\x0e-\x1f\x7f])'), CHECK(content !~* '(-----BEGIN|Bearer[[:space:]]+|\msk[-_][A-Za-z0-9_-]+|\meyJ[A-Za-z0-9_-]+\.eyJ|(?:api[ _-]?key|password|secret|authorization)[[:space:]]*[:=]|https?://|\mwww\.|[\x01-\x08\x0b\x0c\x0e-\x1f\x7f])')
);
CREATE FUNCTION hon.guard_chad_follow_up() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,hon AS $$
BEGIN IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'IMMUTABLE_CHAD_FOLLOW_UP' USING ERRCODE='42501'; END IF; IF TG_TABLE_NAME='chad_follow_up_invocations' AND ((to_jsonb(NEW)-ARRAY['plan_id','status','reason','reserved_credits','action_request_id','usage_id','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['plan_id','status','reason','reserved_credits','action_request_id','usage_id','updated_at']) OR (OLD.plan_id IS NOT NULL AND NEW.plan_id IS DISTINCT FROM OLD.plan_id) OR (OLD.action_request_id IS NOT NULL AND NEW.action_request_id IS DISTINCT FROM OLD.action_request_id) OR (OLD.usage_id IS NOT NULL AND NEW.usage_id IS DISTINCT FROM OLD.usage_id)) THEN RAISE EXCEPTION 'IMMUTABLE_CHAD_FOLLOW_UP' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['chad_follow_up_invocations','chad_follow_up_drafts'] LOOP EXECUTE format('ALTER TABLE hon.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE hon.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON hon.%I FROM PUBLIC',t);EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON hon.%I FOR EACH ROW EXECUTE FUNCTION hon.guard_chad_follow_up()',t||'_immutable',t);EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON hon.%I FOR EACH STATEMENT EXECUTE FUNCTION hon.guard_chad_follow_up()',t||'_no_truncate',t);END LOOP;END $$;

CREATE FUNCTION hon.resolve_chad_follow_up_scope(p_subject text) RETURNS TABLE(principal_id uuid,organization_id uuid,school_id uuid) LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
 WITH eligible AS (SELECT DISTINCT p.id principal_id,g.organization_id,g.school_id FROM hon.users u JOIN hon.principals p ON p.user_id=u.id JOIN hon.principal_role_grants g ON g.principal_id=p.id JOIN hon.organizations o ON o.id=g.organization_id AND o.status='ACTIVE' JOIN hon.schools s ON s.id=g.school_id AND s.organization_id=g.organization_id AND s.status='ACTIVE' WHERE u.external_subject=p_subject AND p.principal_type='HUMAN_USER' AND p.is_active AND (SELECT count(*) FROM hon.principals x WHERE x.user_id=u.id AND x.principal_type='HUMAN_USER' AND x.is_active)=1 AND NOT EXISTS(SELECT 1 FROM hon.hq_operator_grants h WHERE h.principal_id=p.id) AND NOT EXISTS(SELECT 1 FROM hon.principal_role_grants x JOIN hon.roles r ON r.id=x.role_id AND r.organization_id=x.organization_id WHERE x.principal_id=p.id AND r.code IN('PARENT','GUARDIAN','STUDENT','FAMILY','HQ') AND x.revoked_at IS NULL AND x.effective_from<=clock_timestamp() AND (x.effective_until IS NULL OR x.effective_until>clock_timestamp())) AND hon.staff_member_eligible(p.id,g.organization_id,g.school_id) AND EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=g.organization_id AND e.status='ACTIVE' AND e.tier='COMPLETE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp())) AND NOT EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=g.organization_id AND e.status='ACTIVE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp()) AND e.tier<>'COMPLETE') AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['crm.lead.read','crm.assistant.follow_up_draft','ai.invocation.plan']) q(code) WHERE NOT hon.principal_has_school_permission(p.id,g.organization_id,g.school_id,q.code))) SELECT principal_id,organization_id,school_id FROM eligible WHERE (SELECT count(*) FROM eligible)=1 $$;
CREATE FUNCTION hon.require_chad_follow_up_actor(p_subject text) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$
 DECLARE actor uuid;org uuid:=hon.current_organization_id();school uuid:=hon.current_school_id();
 BEGIN IF current_setting('app.hon_principal_type',true) IS DISTINCT FROM 'HUMAN_USER' OR current_setting('app.hon_source',true) IS DISTINCT FROM 'HUMAN_UI' OR nullif(current_setting('app.hon_action_request_id',true),'') IS NOT NULL OR nullif(current_setting('app.hon_delegated_by_principal_id',true),'') IS NOT NULL THEN RAISE EXCEPTION 'CHAD_HUMAN_STAFF_REQUIRED' USING ERRCODE='42501';END IF;SELECT p.id INTO actor FROM hon.principals p JOIN hon.users u ON u.id=p.user_id WHERE u.external_subject=p_subject AND p.id::text=current_setting('app.hon_principal_id',true);IF actor IS NULL OR NOT hon.staff_member_eligible(actor,org,school) OR NOT EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=org AND e.status='ACTIVE' AND e.tier='COMPLETE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp())) OR EXISTS(SELECT 1 FROM hon.organization_entitlements e WHERE e.organization_id=org AND e.status='ACTIVE' AND e.effective_from<=clock_timestamp() AND (e.effective_until IS NULL OR e.effective_until>clock_timestamp()) AND e.tier<>'COMPLETE') OR NOT hon.principal_has_school_permission(actor,org,school,'crm.lead.read') OR NOT hon.principal_has_school_permission(actor,org,school,'crm.assistant.follow_up_draft') OR NOT hon.principal_has_school_permission(actor,org,school,'ai.invocation.plan') THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_FORBIDDEN' USING ERRCODE='42501';END IF;RETURN actor;END $$;
CREATE FUNCTION hon.chad_follow_up_event(p_id uuid,p_event text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE i hon.chad_follow_up_invocations%ROWTYPE;rid uuid:=nullif(current_setting('app.hon_request_id',true),'')::uuid;payload jsonb;BEGIN SELECT * INTO STRICT i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id();payload:=jsonb_build_object('invocationId',i.id,'leadId',i.lead_id,'leadVersion',i.lead_version,'workItemId',i.work_item_id,'status',i.status,'reason',i.reason,'contentProposalOnly',true,'delivery','NOT_CREATED_OR_SENT');INSERT INTO hon.audit_events(organization_id,school_id,actor_principal_id,source,action_code,entity_type,entity_id,next_state,result,request_id,correlation_id,action_request_id) VALUES(i.organization_id,i.school_id,nullif(current_setting('app.hon_principal_id',true),'')::uuid,'HUMAN_UI',p_event,'CHAD_FOLLOW_UP_INVOCATION',i.id,payload,'SUCCEEDED',rid,rid,i.action_request_id);INSERT INTO hon.outbox_events(organization_id,school_id,event_type,schema_version,aggregate_type,aggregate_id,aggregate_version,correlation_id,causation_id,payload) VALUES(i.organization_id,i.school_id,p_event,1,'CHAD_FOLLOW_UP_INVOCATION',i.id,1,rid,rid,payload);END $$;
CREATE FUNCTION hon.read_chad_follow_up_invocation(p_subject text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);result jsonb;BEGIN SELECT jsonb_build_object('id',i.id,'schoolId',i.school_id,'leadId',i.lead_id,'leadVersion',i.lead_version,'purpose',i.purpose,'workItemId',i.work_item_id,'status',CASE WHEN i.status='SENDING' AND i.updated_at<clock_timestamp()-interval '30 seconds' THEN 'UNKNOWN' ELSE i.status END,'reason',i.reason,'actionRequestId',i.action_request_id,'draft',CASE WHEN d.invocation_id IS NULL THEN NULL ELSE jsonb_build_object('subject',d.subject,'content',d.content) END,'inputTokens',u.input_units,'outputTokens',u.output_units,'providerCostMicrounits',u.provider_cost_microunits,'customerCredits',u.customer_credits,'delivery','NOT_CREATED_OR_SENT') INTO result FROM hon.chad_follow_up_invocations i LEFT JOIN hon.chad_follow_up_drafts d ON d.invocation_id=i.id LEFT JOIN hon.ai_usage_ledger u ON u.id=i.usage_id WHERE i.id=p_id AND i.organization_id=hon.current_organization_id() AND i.school_id=hon.current_school_id() AND i.requested_by=actor;IF result IS NULL THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_NOT_FOUND' USING ERRCODE='P0002';END IF;RETURN result;END $$;
CREATE FUNCTION hon.begin_chad_follow_up_request(p_subject text,p_input jsonb,p_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);org uuid:=hon.current_organization_id();school uuid:=hon.current_school_id();l hon.crm_leads%ROWTYPE;i hon.chad_follow_up_invocations%ROWTYPE;wid uuid;fp text;BEGIN IF p_key IS NULL OR p_input IS NULL OR jsonb_typeof(p_input)<>'object' OR NOT p_input ?& ARRAY['leadId','expectedLeadVersion','purpose'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k WHERE k NOT IN('leadId','expectedLeadVersion','purpose')) OR jsonb_typeof(p_input->'leadId')<>'string' OR p_input->>'leadId' !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' OR jsonb_typeof(p_input->'expectedLeadVersion')<>'number' OR p_input->>'expectedLeadVersion' !~ '^[1-9][0-9]{0,8}$' OR jsonb_typeof(p_input->'purpose')<>'string' OR p_input->>'purpose' NOT IN('INTRODUCTION','CHECK_IN','TRIAL_REMINDER','REENGAGEMENT') THEN RAISE EXCEPTION 'INVALID_CHAD_FOLLOW_UP_REQUEST' USING ERRCODE='22023';END IF;fp:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE organization_id=org AND school_id=school AND requested_by=actor AND idempotency_key=p_key FOR UPDATE;IF FOUND THEN IF i.request_hash<>fp THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_REPLAY_SWAP' USING ERRCODE='23505';END IF;RETURN hon.read_chad_follow_up_invocation(p_subject,i.id);END IF;SELECT * INTO l FROM hon.crm_leads WHERE id=(p_input->>'leadId')::uuid AND organization_id=org AND school_id=school AND status='OPEN' FOR SHARE;IF NOT FOUND OR l.version<>(p_input->>'expectedLeadVersion')::integer THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_LEAD_UNAVAILABLE' USING ERRCODE='P0002';END IF;INSERT INTO hon.work_items(organization_id,school_id,work_type,status,subject_type,subject_id,payload,correlation_id) VALUES(org,school,'AI_DRAFT_FOLLOW_UP','READY','CRM_LEAD',l.id,'{}',nullif(current_setting('app.hon_request_id',true),'')::uuid) RETURNING id INTO wid;INSERT INTO hon.chad_follow_up_invocations(organization_id,school_id,requested_by,lead_id,lead_version,purpose,work_item_id,request_hash,idempotency_key) VALUES(org,school,actor,l.id,l.version,p_input->>'purpose',wid,fp,p_key) RETURNING * INTO i;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.requested');RETURN hon.read_chad_follow_up_invocation(p_subject,i.id);END $$;
CREATE FUNCTION hon.chad_follow_up_planning_reference(p_subject text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);i hon.chad_follow_up_invocations%ROWTYPE;w hon.work_items%ROWTYPE;BEGIN SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_NOT_FOUND' USING ERRCODE='P0002';END IF;IF i.status='SENDING' AND i.updated_at<clock_timestamp()-interval '30 seconds' THEN UPDATE hon.chad_follow_up_invocations SET status='UNKNOWN',reason='PROVIDER_UNKNOWN',updated_at=clock_timestamp() WHERE id=i.id;UPDATE hon.work_items SET status='NEEDS_ATTENTION',version=version+1 WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.unknown');RETURN NULL;END IF;IF i.status NOT IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED') THEN RETURN NULL;END IF;SELECT * INTO STRICT w FROM hon.work_items WHERE id=i.work_item_id AND organization_id=i.organization_id AND school_id=i.school_id FOR UPDATE;IF i.plan_id IS NULL AND w.status<>'READY' THEN UPDATE hon.work_items SET status='READY',version=version+1 WHERE id=w.id RETURNING * INTO w;END IF;RETURN jsonb_build_object('planId',i.plan_id,'workItemId',w.id,'workVersion',w.version);END $$;
CREATE FUNCTION hon.prepare_chad_follow_up_invocation(p_subject text,p_id uuid,p_plan uuid,p_ready boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);i hon.chad_follow_up_invocations%ROWTYPE;p hon.ai_invocation_plans%ROWTYPE;l hon.crm_leads%ROWTYPE;why text;used numeric;reserved numeric;facts jsonb;BEGIN SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_NOT_FOUND' USING ERRCODE='P0002';END IF;IF i.status NOT IN('PENDING','CONFIGURATION_REQUIRED','BLOCKED') THEN RETURN NULL;END IF;IF p_plan IS NULL THEN why:='NO_ELIGIBLE_ROUTE';ELSE SELECT * INTO p FROM hon.ai_invocation_plans WHERE id=p_plan AND organization_id=i.organization_id AND school_id=i.school_id AND work_item_id=i.work_item_id AND task_class='DRAFT_FOLLOW_UP' AND agent_key='chad' AND input_budget=2048 AND output_budget=600 AND max_provider_cost_microunits=60000;IF NOT FOUND OR (i.plan_id IS NOT NULL AND i.plan_id<>p_plan) THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_PLAN_SWAP' USING ERRCODE='42501';END IF;IF p.provider_id<>'OPENROUTER' THEN why:='UNSUPPORTED_PROVIDER';ELSIF NOT p_ready THEN why:='CONFIGURATION_REQUIRED';END IF;END IF;SELECT * INTO l FROM hon.crm_leads WHERE id=i.lead_id AND organization_id=i.organization_id AND school_id=i.school_id AND status='OPEN' FOR SHARE;IF NOT FOUND OR l.version<>i.lead_version THEN why:='LEAD_STALE';END IF;SELECT coalesce(sum(customer_credits),0) INTO used FROM hon.ai_usage_ledger WHERE organization_id=i.organization_id AND occurred_at>=date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AND occurred_at<(date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC')+interval '1 month') AT TIME ZONE 'UTC';SELECT coalesce(sum(reserved_credits),0) INTO reserved FROM hon.chad_follow_up_invocations WHERE organization_id=i.organization_id;IF why IS NULL AND used+reserved+p.customer_credit_estimate>12000 THEN why:='CUSTOMER_BUDGET_EXCEEDED';END IF;UPDATE hon.chad_follow_up_invocations SET plan_id=p.id,status=CASE WHEN why IS NULL THEN 'SENDING' WHEN why='CONFIGURATION_REQUIRED' THEN 'CONFIGURATION_REQUIRED' ELSE 'BLOCKED' END,reason=why,reserved_credits=CASE WHEN why IS NULL THEN p.customer_credit_estimate ELSE 0 END,updated_at=clock_timestamp() WHERE id=i.id;UPDATE hon.work_items SET status=CASE WHEN why IS NULL THEN 'WORKING' ELSE 'NEEDS_ATTENTION' END,version=version+1,updated_at=clock_timestamp() WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.prepared');IF why IS NOT NULL THEN RETURN NULL;END IF;facts:=jsonb_build_object('purpose',i.purpose,'leadStatus',l.status,'pipelineStageId',l.pipeline_stage_id,'sourceCode',l.source_code,'programInterestCode',l.program_interest_code,'nextFollowUpAt',l.next_follow_up_at,'leadVersion',l.version);RETURN jsonb_build_object('providerId',p.provider_id,'modelId',p.model_id,'providerRequestId',i.provider_request_id,'request','Approved non-identifying lead facts only: '||facts::text,'inputBudget',p.input_budget,'outputBudget',p.output_budget,'maxCostMicrounits',p.max_provider_cost_microunits);END $$;
CREATE FUNCTION hon.fail_chad_follow_up_invocation(p_subject text,p_id uuid,p_outcome text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);i hon.chad_follow_up_invocations%ROWTYPE;BEGIN IF p_outcome NOT IN('PRE_SEND','FAILED','UNKNOWN') OR p_reason NOT IN('CONFIGURATION_REQUIRED','UNSUPPORTED_PROVIDER','INVALID_REQUEST','PROVIDER_REJECTED','PROVIDER_UNKNOWN') THEN RAISE EXCEPTION 'INVALID_CHAD_FOLLOW_UP_OUTCOME' USING ERRCODE='22023';END IF;SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE;IF NOT FOUND OR i.status<>'SENDING' THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_OUTCOME_REPLAY' USING ERRCODE='40001';END IF;UPDATE hon.chad_follow_up_invocations SET status=CASE WHEN p_outcome='PRE_SEND' THEN 'CONFIGURATION_REQUIRED' ELSE p_outcome END,reason=p_reason,reserved_credits=CASE WHEN p_outcome='UNKNOWN' THEN reserved_credits ELSE 0 END,updated_at=clock_timestamp() WHERE id=i.id;UPDATE hon.work_items SET status='NEEDS_ATTENTION',version=version+1 WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.provider_result');END $$;
CREATE FUNCTION hon.record_chad_follow_up_result(p_subject text,p_id uuid,p_result jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);i hon.chad_follow_up_invocations%ROWTYPE;p hon.ai_invocation_plans%ROWTYPE;d jsonb:=p_result->'draft';uid uuid;credits integer;over boolean;BEGIN SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE;IF NOT FOUND OR i.status<>'SENDING' OR i.usage_id IS NOT NULL THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_OUTCOME_REPLAY' USING ERRCODE='40001';END IF;SELECT * INTO STRICT p FROM hon.ai_invocation_plans WHERE id=i.plan_id;IF p_result IS NULL OR jsonb_typeof(p_result)<>'object' OR NOT p_result ?& ARRAY['draft','inputTokens','outputTokens','providerCostMicrounits'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_result) k WHERE k NOT IN('draft','inputTokens','outputTokens','providerCostMicrounits')) OR jsonb_typeof(d)<>'object' OR NOT d ?& ARRAY['subject','content'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d) k WHERE k NOT IN('subject','content')) OR jsonb_typeof(d->'subject')<>'string' OR jsonb_typeof(d->'content')<>'string' OR length(btrim(d->>'subject')) NOT BETWEEN 1 AND 120 OR length(btrim(d->>'content')) NOT BETWEEN 1 AND 3000 OR (p_result->>'inputTokens')!~'^[0-9]+$' OR (p_result->>'outputTokens')!~'^[0-9]+$' OR (p_result->>'providerCostMicrounits')!~'^[0-9]+$' THEN RAISE EXCEPTION 'INVALID_CHAD_FOLLOW_UP_RESULT' USING ERRCODE='22023';END IF;credits:=((p_result->>'inputTokens')::integer+(p_result->>'outputTokens')::integer+999)/1000;over:=(p_result->>'inputTokens')::integer>p.input_budget OR (p_result->>'outputTokens')::integer>p.output_budget OR (p_result->>'providerCostMicrounits')::bigint>p.max_provider_cost_microunits OR credits>i.reserved_credits;INSERT INTO hon.ai_usage_ledger(organization_id,school_id,initiator_principal_id,work_item_id,provider_code,model_code,modality,input_units,output_units,provider_cost_microunits,customer_credits,correlation_id) VALUES(i.organization_id,i.school_id,actor,i.work_item_id,p.provider_id,p.model_id,'TEXT',(p_result->>'inputTokens')::bigint,(p_result->>'outputTokens')::bigint,(p_result->>'providerCostMicrounits')::bigint,credits,nullif(current_setting('app.hon_request_id',true),'')::uuid) RETURNING id INTO uid;UPDATE hon.chad_follow_up_invocations SET usage_id=uid,reserved_credits=0,status=CASE WHEN over THEN 'FAILED' ELSE status END,reason=CASE WHEN over THEN 'RESULT_BUDGET_EXCEEDED' ELSE NULL END WHERE id=i.id;IF over THEN UPDATE hon.work_items SET status='FAILED',version=version+1 WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.budget_failed');RETURN NULL;END IF;INSERT INTO hon.chad_follow_up_drafts(invocation_id,organization_id,school_id,lead_id,subject,content) VALUES(i.id,i.organization_id,i.school_id,i.lead_id,d->>'subject',d->>'content');RETURN jsonb_build_object('invocationId',i.id,'leadId',i.lead_id,'leadVersion',i.lead_version,'purpose',i.purpose,'subject',d->>'subject','content',d->>'content','delivery','NOT_CREATED_OR_SENT');END $$;
CREATE FUNCTION hon.bind_chad_follow_up_proposal(p_subject text,p_id uuid,p_action uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE actor uuid:=hon.require_chad_follow_up_actor(p_subject);i hon.chad_follow_up_invocations%ROWTYPE;d hon.chad_follow_up_drafts%ROWTYPE;BEGIN SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE id=p_id AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() AND requested_by=actor FOR UPDATE;SELECT * INTO STRICT d FROM hon.chad_follow_up_drafts WHERE invocation_id=i.id;IF i.status<>'SENDING' OR i.action_request_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM hon.action_requests a WHERE a.id=p_action AND a.organization_id=i.organization_id AND a.school_id=i.school_id AND a.requested_by_principal_id=actor AND a.action_code='crm.follow_up_draft.propose' AND a.required_permission='crm.assistant.follow_up_draft' AND a.effective_authority_mode='CONFIRM' AND a.status='AWAITING_APPROVAL' AND a.normalized_payload=jsonb_build_object('invocationId',i.id,'leadId',i.lead_id,'leadVersion',i.lead_version,'purpose',i.purpose,'subject',d.subject,'content',d.content,'delivery','NOT_CREATED_OR_SENT')) THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_ACTION_BINDING' USING ERRCODE='42501';END IF;UPDATE hon.chad_follow_up_invocations SET action_request_id=p_action,status='AWAITING_APPROVAL',updated_at=clock_timestamp() WHERE id=i.id;UPDATE hon.work_items SET status='WAITING_FOR_APPROVAL',version=version+1 WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,'chad.follow_up_draft.proposed');END $$;
CREATE FUNCTION hon.chad_follow_up_draft_is_current(p_action uuid,p_payload jsonb) RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ SELECT EXISTS(SELECT 1 FROM hon.chad_follow_up_invocations i JOIN hon.chad_follow_up_drafts d ON d.invocation_id=i.id JOIN hon.crm_leads l ON l.id=i.lead_id AND l.organization_id=i.organization_id AND l.school_id=i.school_id WHERE i.action_request_id=p_action AND i.organization_id=hon.current_organization_id() AND i.school_id=hon.current_school_id() AND i.status='AWAITING_APPROVAL' AND l.status='OPEN' AND l.version=i.lead_version AND p_payload=jsonb_build_object('invocationId',i.id,'leadId',i.lead_id,'leadVersion',i.lead_version,'purpose',i.purpose,'subject',d.subject,'content',d.content,'delivery','NOT_CREATED_OR_SENT')) $$;
CREATE FUNCTION hon.transition_chad_follow_up_draft(p_action uuid,p_decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,hon AS $$ DECLARE i hon.chad_follow_up_invocations%ROWTYPE;BEGIN IF p_decision NOT IN('APPROVED','DENIED') OR NOT hon.human_action_reviewer() THEN RAISE EXCEPTION 'REVIEW_REQUIRED' USING ERRCODE='42501';END IF;SELECT * INTO i FROM hon.chad_follow_up_invocations WHERE action_request_id=p_action AND organization_id=hon.current_organization_id() AND school_id=hon.current_school_id() FOR UPDATE;IF NOT FOUND OR i.status<>'AWAITING_APPROVAL' OR NOT EXISTS(SELECT 1 FROM hon.action_requests a JOIN hon.action_approvals ap ON ap.action_request_id=a.id WHERE a.id=p_action AND a.status=p_decision::hon.action_request_status AND ap.decision=p_decision::hon.approval_decision AND ap.reviewed_payload_hash=a.payload_hash AND ap.reviewed_policy_version=a.policy_version AND ap.reviewer_principal_id<>i.requested_by) THEN RAISE EXCEPTION 'CHAD_FOLLOW_UP_DECISION_BINDING' USING ERRCODE='42501';END IF;UPDATE hon.chad_follow_up_invocations SET status=p_decision,updated_at=clock_timestamp() WHERE id=i.id;UPDATE hon.work_items SET status=CASE WHEN p_decision='APPROVED' THEN 'COMPLETED' ELSE 'FAILED' END,version=version+1,result=jsonb_build_object('invocationId',i.id,'leadId',i.lead_id,'contentProposalOnly',true,'delivery','NOT_CREATED_OR_SENT') WHERE id=i.work_item_id;PERFORM hon.chad_follow_up_event(i.id,CASE WHEN p_decision='APPROVED' THEN 'chad.follow_up_draft.approved' ELSE 'chad.follow_up_draft.rejected' END);END $$;
DO $$ DECLARE f regprocedure;r text;BEGIN FOREACH f IN ARRAY ARRAY['hon.guard_chad_follow_up()'::regprocedure,'hon.resolve_chad_follow_up_scope(text)'::regprocedure,'hon.require_chad_follow_up_actor(text)'::regprocedure,'hon.chad_follow_up_event(uuid,text)'::regprocedure,'hon.read_chad_follow_up_invocation(text,uuid)'::regprocedure,'hon.begin_chad_follow_up_request(text,jsonb,uuid)'::regprocedure,'hon.chad_follow_up_planning_reference(text,uuid)'::regprocedure,'hon.prepare_chad_follow_up_invocation(text,uuid,uuid,boolean)'::regprocedure,'hon.fail_chad_follow_up_invocation(text,uuid,text,text)'::regprocedure,'hon.record_chad_follow_up_result(text,uuid,jsonb)'::regprocedure,'hon.bind_chad_follow_up_proposal(text,uuid,uuid)'::regprocedure,'hon.chad_follow_up_draft_is_current(uuid,jsonb)'::regprocedure,'hon.transition_chad_follow_up_draft(uuid,text)'::regprocedure] LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f);END LOOP;IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='hon_runtime') THEN REVOKE ALL ON hon.chad_follow_up_invocations,hon.chad_follow_up_drafts FROM hon_runtime;GRANT EXECUTE ON FUNCTION hon.resolve_chad_follow_up_scope(text),hon.read_chad_follow_up_invocation(text,uuid),hon.begin_chad_follow_up_request(text,jsonb,uuid),hon.chad_follow_up_planning_reference(text,uuid),hon.prepare_chad_follow_up_invocation(text,uuid,uuid,boolean),hon.fail_chad_follow_up_invocation(text,uuid,text,text),hon.record_chad_follow_up_result(text,uuid,jsonb),hon.bind_chad_follow_up_proposal(text,uuid,uuid),hon.chad_follow_up_draft_is_current(uuid,jsonb),hon.transition_chad_follow_up_draft(uuid,text) TO hon_runtime;END IF;FOR r IN SELECT rolname FROM pg_roles WHERE rolname IN('anon','authenticated','service_role') LOOP EXECUTE format('REVOKE ALL ON hon.chad_follow_up_invocations,hon.chad_follow_up_drafts FROM %I',r);END LOOP;END $$;
COMMIT;
